// Tempo-Messung (SEO-Finale, Paket TEMPO): CLS, LCP, lange Tasks, Bytes, Bild-Audit.
// Aufruf: node tempo-mess.mjs <basis> <breite> <läufe> <pfad1> <pfad2> ...
// Gibt je Pfad den Median über die Läufe aus (JSON-Zeilen).
import { chromium } from "playwright";

const [basis, breiteArg = "1440", laeufeArg = "3", ...pfade] = process.argv.slice(2);
const w = Number(breiteArg);
const laeufe = Number(laeufeArg);
const browser = await chromium.launch();

function median(a) { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; }

for (const pfad of pfade) {
  const runs = [];
  let bilder = null;
  for (let i = 0; i < laeufe; i++) {
    const ctx = await browser.newContext({ viewport: { width: w, height: w < 700 ? 844 : 900 } });
    await ctx.addInitScript(() => {
      try { localStorage.setItem("cookie-consent", "necessary"); } catch {}
      window.__cls = 0; window.__long = 0; window.__longms = 0; window.__lcp = 0;
      new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) window.__cls += e.value; }).observe({ type: "layout-shift", buffered: true });
      new PerformanceObserver((l) => { for (const e of l.getEntries()) { window.__long++; window.__longms += e.duration; } }).observe({ type: "longtask", buffered: true });
      new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lcp = e.startTime; }).observe({ type: "largest-contentful-paint", buffered: true });
    });
    const page = await ctx.newPage();
    try {
      await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
      await page.waitForTimeout(2500);
      const m = await page.evaluate(() => {
        const nav = performance.getEntriesByType("navigation")[0] || {};
        const res = performance.getEntriesByType("resource");
        const kb = (f) => Math.round(res.filter(f).reduce((s, r) => s + (r.transferSize || 0), 0) / 1024);
        return {
          cls: +window.__cls.toFixed(4),
          lcp: Math.round(window.__lcp),
          long: window.__long,
          longms: Math.round(window.__longms),
          dcl: Math.round(nav.domContentLoadedEventEnd || 0),
          load: Math.round(nav.loadEventEnd || 0),
          jsKB: kb((r) => r.initiatorType === "script" || /\.js(\?|$)/.test(r.name)),
          imgKB: kb((r) => r.initiatorType === "img" || /\.(png|jpe?g|webp|avif|svg|gif)(\?|$)/.test(r.name)),
          gesamtKB: kb(() => true),
        };
      });
      runs.push(m);
      if (i === 0) {
        bilder = await page.evaluate(() => Array.from(document.images)
          .filter((img) => img.naturalWidth > 0 && img.clientWidth > 0)
          .map((img) => ({
            src: (img.currentSrc || img.src).split("/").slice(-1)[0].slice(0, 80),
            natur: img.naturalWidth,
            anzeige: img.clientWidth,
            dpr: +(img.naturalWidth / img.clientWidth).toFixed(1),
            attrWH: img.getAttribute("width") !== null && img.getAttribute("height") !== null,
            sizes: img.getAttribute("sizes") || "",
          }))
          .filter((b) => b.dpr > 2.5 || !b.attrWH));
      }
    } catch (e) {
      runs.push({ fehler: String(e).slice(0, 100) });
    }
    await ctx.close();
  }
  const ok = runs.filter((r) => !r.fehler);
  if (!ok.length) { console.log(JSON.stringify({ pfad, w, fehler: runs[0].fehler })); continue; }
  const med = {};
  for (const k of Object.keys(ok[0])) med[k] = median(ok.map((r) => r[k]));
  console.log(JSON.stringify({ pfad, w, laeufe: ok.length, ...med, bilderAuffaellig: bilder?.length ? bilder : undefined }));
}
await browser.close();

